// The Expo app kit: a phone app made with Expo and React Native. In this
// first version it runs in the browser, through Expo's web support; the
// phone emulators come later. It makes a new one with Expo's own starter.
import { basename } from "node:path";
import { defineKit } from "@software-factory/core";
import { commandsOf, doesOf, readableName, readPackageJson, verifyCommand, } from "./package-json.js";
const PORT = 8081;
export const expoApp = defineKit({
    id: "expo-app",
    name: "Expo app",
    about: "A phone app made with Expo and React Native.",
    kind: "expo-app",
    commands: { start: "npx expo start" },
    rules: ["rules/expo-app/conventions.md", "rules/expo-app/lessons.md"],
    port: PORT,
    detect: (folder) => {
        const file = readPackageJson(folder);
        if (!file?.packages.has("expo"))
            return null;
        return {
            name: readableName(file, folder),
            commands: commandsOf({
                start: file.scripts.has("start") ? "npm start" : undefined,
                verify: verifyCommand(file),
            }),
        };
    },
    partsFor: (product) => {
        const port = product.port ?? PORT;
        return [
            {
                id: product.id,
                name: product.name,
                area: "products",
                does: doesOf(product, "phone app, in the browser"),
                dependsOn: product.dependsOn,
                folder: product.folder,
                prepare: [{ label: "Installing packages", packages: true }],
                run: ["npx", "expo", "start", "--web", "--port", String(port)],
                // No browser opens by itself, and Expo asks nothing on the terminal.
                env: { BROWSER: "none", CI: "1" },
                port: { fixed: port },
                health: "/",
                open: "/",
                start: "auto",
                startSeconds: 240,
            },
        ];
    },
    create: (folder) => [
        [
            "npx",
            "create-expo-app@latest",
            basename(folder),
            "--template",
            "blank-typescript",
            "--yes",
        ],
    ],
});
